"""Install the permanent Dantzig workflow and launch one independent rerun."""

import argparse
import base64
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import shutil
import sys
import zlib


SERVER_REPO = Path("/local/scratch/a/lee4382/repository/RBFopt_Test")
PAYLOAD = ""
PAYLOAD_SHA256 = "75d8551a738de94e3f871104208ea279d378f08aaa3aca5611dc9763e77f1885"


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def install(repo):
    raw = zlib.decompress(base64.b64decode(PAYLOAD))
    if hashlib.sha256(raw).hexdigest() != PAYLOAD_SHA256:
        raise ValueError("Embedded workflow hash mismatch")
    files = json.loads(raw)
    origin = json.loads(files["reference_origin.json"])
    source = repo / "results/dsda_abs1e5_input_20261027_2320_sharedcpu_v2"
    if sha(source / "SHA256SUMS.json") != origin["reference_seal_sha256"]:
        raise ValueError("Existing server input seal differs from the completed experiment")
    reference = json.loads((source / "SHA256SUMS.json").read_text())
    for name, digest in reference.items():
        p = PurePosixPath(name)
        if p.is_absolute() or ".." in p.parts or sha(source / name) != digest:
            raise ValueError("Existing server input mismatch: " + name)
    project = repo / "experiments/dsda_abs1e5"
    expected = {name: hashlib.sha256(text.encode()).hexdigest() for name, text in files.items()}
    if project.exists():
        marker = project / "INSTALL.json"
        if not marker.exists() or json.loads(marker.read_text()).get("payload_sha256") != PAYLOAD_SHA256:
            raise FileExistsError("A different workflow already exists; it was not overwritten: " + str(project))
        for name, digest in expected.items():
            if sha(project / name) != digest:
                raise ValueError("Installed workflow has user changes; preserving them: " + name)
        for name, digest in reference.items():
            if sha(project / "reference" / name) != digest:
                raise ValueError("Installed reference mismatch: " + name)
        print("Existing identical workflow verified:", project, flush=True)
        return project
    staging = repo / "experiments" / (".dsda_abs1e5_install_" + str(os.getpid()))
    staging.mkdir(parents=True, exist_ok=False)
    for name, text in files.items():
        target = staging / name
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(text)
    for name in reference:
        target = staging / "reference" / name
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source / name, target)
    shutil.copy2(source / "SHA256SUMS.json", staging / "reference/SHA256SUMS.json")
    (staging / "INSTALL.json").write_text(json.dumps(dict(payload_sha256=PAYLOAD_SHA256, files_sha256=expected,
        reference_origin=origin, original_input_preserved=str(source)), indent=2) + "\n")
    staging.rename(project)
    print("Installed permanent workflow:", project, flush=True)
    return project


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--install-only", action="store_true")
    args = parser.parse_args()
    repo = Path(__file__).resolve().parent
    if repo != SERVER_REPO:
        raise RuntimeError("Place this file in the Dantzig RBFopt_Test repository root")
    expected_python = repo / ".venv-dantzig/bin/python"
    if Path(sys.executable).absolute() != expected_python:
        raise RuntimeError("Run this file with the existing .venv-dantzig/bin/python")
    project = install(repo)
    if args.install_only:
        print("Installation only; no full experiment started.", flush=True)
        return
    os.execv(sys.executable, [sys.executable, str(project / "launch.py")])


if __name__ == "__main__":
    main()
